#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
bool allUpper(const string&s){for(char c:s)if(!isupper((unsigned char)c))return false;return true;}
bool allLower(const string&s){for(char c:s)if(!islower((unsigned char)c))return false;return true;}
int main(){string w;cin>>w;
bool ok=allUpper(w)||allLower(w)||(isupper((unsigned char)w[0])&&allLower(w.substr(1)));
printf("%s\n",ok?"YES":"NO");return 0;}

